use vstd::prelude::*;

verus! {

// Specification function for the input date string:
// It must be a vector of length 10 starting with ['2','0','1','7']
// and the rest can be any chars.
spec fn is_input_date(date_str: Seq<char>) -> bool {
    date_str.len() == 10_usize.into() &&
    date_str.index(0) == '2' as char &&
    date_str.index(1) == '0' as char &&
    date_str.index(2) == '1' as char &&
    date_str.index(3) == '7' as char
}

// Specification function for the output date string:
// The first 4 chars must be ['2','0','1','8']
// and the chars from index 4 to 9 remain the same as input.
spec fn is_output_date(orig: Seq<char>, result: Seq<char>) -> bool {
    result.len() == 10_usize.into() &&
    result.index(0) == '2' as char &&
    result.index(1) == '0' as char &&
    result.index(2) == '1' as char &&
    result.index(3) == '8' as char &&
    forall|i: int| 4 <= i && i < 10 ==> result.index(i) == orig.index(i)
}

fn solve(date_str: Vec<char>) -> Vec<char>
    requires
        // input matches the required format
        is_input_date(SEq::from_vec(&date_str)),
    ensures
        // output matches the spec
        is_output_date(SEq::from_vec(&date_str), SEq::from_vec(&result)),
{
    let mut result = Vec::with_capacity(10);

    // push '2','0','1','8' as prefix
    result.push('2');
    result.push('0');
    result.push('1');
    result.push('8');

    // append unchanged chars from index 4..=9
    result.extend(date_str.iter().skip(4).take(6));

    result
}

}